import AudioToolbox
@preconcurrency import AVFoundation
import Darwin
import Domain
import Foundation
import Logging
import OSLog

// MARK: - MicCaptureActor

/// Captures microphone audio via AVAudioEngine, converts on-the-fly to
/// 16 kHz mono Float32, and emits TaggedAudioBuffers tagged as `.microphone`.
public actor MicCaptureActor {
    private let micQueue = DispatchSerialQueue(label: "com.therecord.micaudio", qos: .userInitiated)
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        micQueue.asUnownedSerialExecutor()
    }

    /// Internal (not private) so the route-change extension in a separate file can access them.
    enum State { case idle, recording }

    var state: State = .idle
    var engine: AVAudioEngine?
    var bridge: MicTapBridge?
    var continuation: AsyncThrowingStream<TaggedAudioBuffer, Error>.Continuation?

    /// Mach host-time tick for the current session start; used to re-create
    /// `MicTapBridge` after a route change (#49).
    var sessionStartTick: UInt64 = 0

    /// Observer token for `AVAudioEngineConfigurationChange` (#49).
    /// Registered in `start()` and removed in `stop()`.
    var routeChangeObserver: NSObjectProtocol?

    /// `true` when VoiceProcessingIO AEC was successfully enabled for the current session.
    /// Resets to `false` when `stop()` is called.
    internal(set) var isUsingVoiceProcessing = false

    /// Stored handle for the permission-revocation polling Task.
    /// Cancelled and nilled in stop() and failFast() so the loop exits promptly.
    var permissionPollTask: Task<Void, Never>?

    let logger = AppLogger.for(category: "MicCapture")
    private let signposter = OSSignposter(subsystem: "com.therecord", category: "Performance")

    public init() {}

    /// Starts mic capture and returns a stream of 16 kHz mono Float32 buffers.
    ///
    /// - Parameter sessionStartTick: Mach host time tick captured at session start. Pass `0` to
    ///   let the actor capture its own T0 at the moment capture begins.
    public func start(sessionStartTick: UInt64) async throws -> AsyncThrowingStream<TaggedAudioBuffer, Error> {
        let signpostState = signposter.beginInterval("MicCaptureActor.start")
        defer { signposter.endInterval("MicCaptureActor.start", signpostState) }

        guard AVAudioApplication.shared.recordPermission == .granted else {
            throw AudioError.permissionDenied(message: "Microphone permission is required")
        }
        guard state == .idle else { throw AudioError.captureFailed(underlying: nil) }

        let eng = AVAudioEngine()
        let (hwFormat, converter) = try configureInputNode(engine: eng)
        let targetFormat = converter.outputFormat

        let t0: UInt64 = sessionStartTick != 0 ? sessionStartTick : mach_absolute_time()
        self.sessionStartTick = t0
        // Bound the stream to prevent unbounded growth (#45).
        let (stream, cont) = AsyncThrowingStream<TaggedAudioBuffer, Error>.makeStream(
            bufferingPolicy: .bufferingNewest(128)
        )
        let tap = MicTapBridge(
            continuation: cont,
            converter: converter,
            targetFormat: targetFormat,
            maxFrameCapacity: 4096,
            sessionStartTick: t0
        )

        eng.inputNode.installTap(onBus: 0, bufferSize: 4096, format: hwFormat) { buffer, when in
            tap.process(buffer, when: when)
        }

        do {
            try eng.start()
        } catch {
            eng.inputNode.removeTap(onBus: 0)
            cont.finish()
            isUsingVoiceProcessing = false
            let errDesc = String(reflecting: error)
            logger.error("Failed to start AVAudioEngine: \(errDesc, privacy: .public)")
            throw AudioError.captureFailed(underlying: error)
        }

        // Register for hardware reconfiguration events (#49).
        // The engine auto-stops on configuration change; we re-arm the tap.
        let observer = NotificationCenter.default.addObserver(
            forName: .AVAudioEngineConfigurationChange,
            object: eng,
            queue: nil
        ) { [weak self] _ in
            Task { await self?.handleConfigurationChange() }
        }
        routeChangeObserver = observer

        setupPermissionPollTask(continuation: cont)

        engine = eng
        bridge = tap
        continuation = cont
        state = .recording
        logger.info("Mic capture started (hw sampleRate=\(hwFormat.sampleRate, privacy: .private))")
        return stream
    }

    /// Stops mic capture, removes the tap, and finishes the stream.
    ///
    /// Throws `AudioError.invalidConfiguration` if no recording is in progress,
    /// as required by the `MicCaptureEngine` protocol contract.
    public func stop() async throws {
        guard state == .recording else {
            throw AudioError.invalidConfiguration(reason: "No recording in progress")
        }
        permissionPollTask?.cancel()
        permissionPollTask = nil
        // Remove route-change observer before tearing down engine (#49).
        if let obs = routeChangeObserver {
            NotificationCenter.default.removeObserver(obs)
            routeChangeObserver = nil
        }
        engine?.inputNode.removeTap(onBus: 0)
        try? engine?.inputNode.setVoiceProcessingEnabled(false)
        engine?.stop()
        continuation?.finish()
        engine = nil
        bridge = nil
        continuation = nil
        isUsingVoiceProcessing = false
        state = .idle
        logger.info("Mic capture stopped")
    }

    /// Returns `true` while actively recording.
    public var isRecording: Bool {
        state == .recording
    }

    func failFast() async {
        guard state == .recording else { return }
        permissionPollTask?.cancel()
        permissionPollTask = nil
        if let obs = routeChangeObserver {
            NotificationCenter.default.removeObserver(obs)
            routeChangeObserver = nil
        }
        engine?.inputNode.removeTap(onBus: 0)
        try? engine?.inputNode.setVoiceProcessingEnabled(false)
        engine = nil
        bridge = nil
        continuation?.finish()
        continuation = nil
        isUsingVoiceProcessing = false
        state = .idle
    }

    private func configureInputNode(engine: AVAudioEngine) throws -> (AVAudioFormat, AVAudioConverter) {
        let inputNode = engine.inputNode

        // Attempt VoiceProcessingIO AEC before reading hwFormat
        do {
            try inputNode.setVoiceProcessingEnabled(true)
            isUsingVoiceProcessing = true
            logger.info("VoiceProcessingIO AEC enabled")
        } catch let err as NSError where err.code == Int(kAudioUnitErr_NoConnection) {
            logger.warning("VoiceProcessingIO unavailable (-10876) — CSpeex AEC fallback will be used")
        } catch {
            let errDesc = String(reflecting: error)
            logger.warning("VoiceProcessingIO failed (\(errDesc, privacy: .public)) — CSpeex AEC fallback will be used")
        }

        let hwFormat = inputNode.outputFormat(forBus: 0)

        guard hwFormat.channelCount > 0, hwFormat.sampleRate > 0 else {
            throw AudioError.captureFailed(underlying: nil)
        }

        guard let targetFormat = AVAudioFormat(
            commonFormat: .pcmFormatFloat32,
            sampleRate: 16000,
            channels: 1,
            interleaved: false
        ) else {
            throw AudioError.invalidConfiguration(reason: "Cannot create 16 kHz mono Float32 format")
        }

        guard let converter = AVAudioConverter(from: hwFormat, to: targetFormat) else {
            throw AudioError.invalidConfiguration(
                reason: "Cannot create audio converter from \(hwFormat) to 16 kHz mono Float32"
            )
        }

        return (hwFormat, converter)
    }

    private func setupPermissionPollTask(continuation: AsyncThrowingStream<TaggedAudioBuffer, Error>.Continuation) {
        permissionPollTask?.cancel()
        permissionPollTask = Task { [weak self, cont = continuation] in
            let profiler = HardwareBoundaryProfiler(category: "Performance")
            do {
                while !Task.isCancelled {
                    try await Task.sleep(for: .seconds(1))
                    guard let self = self else { break }
                    let state = await self.state
                    guard state == .recording else { break }

                    // Emit hardware telemetry
                    await profiler.emitSnapshotEvent("Audio Session Telemetry")

                    if AVAudioApplication.shared.recordPermission != .granted {
                        cont.yield(with: .failure(AudioError.permissionRevoked))
                        await self.failFast()
                        break
                    }
                }
            } catch {
                // CancellationError from Task.sleep exits the loop promptly on cancellation.
            }
        }
    }
}

// MARK: - MicCaptureEngine Conformance

extension MicCaptureActor: MicCaptureEngine {}

