import Foundation
@testable import MLInfrastructure
import Testing

@Suite("SystemHardwarePoller")
struct SystemHardwarePollerTests {
    @Test
    func `fetches valid static system info`() async {
        let poller = SystemHardwarePoller()

        let osVersion = await poller.getOSVersion()
        #expect(!osVersion.isEmpty, "OS Version should not be empty")

        let cpuBrand = await poller.getCPUBrand()
        #expect(!cpuBrand.isEmpty, "CPU Brand should not be empty")

        let memoryMB = await poller.getPhysicalMemoryMB()
        #expect(memoryMB > 0, "Physical memory should be > 0")
    }

    @Test
    func `fetches valid battery info`() async {
        let poller = SystemHardwarePoller()

        let batteryPct = await poller.getBatteryPercentage()
        #expect(batteryPct >= -1 && batteryPct <= 100, "Battery percentage should be between -1 and 100")

        let thermalState = await poller.getThermalState()
        #expect(["Nominal", "Fair", "Serious", "Critical", "Unknown"].contains(thermalState), "Thermal state should be one of the known values")
    }

    @Test
    func `fetches valid resident memory`() async {
        let poller = SystemHardwarePoller()

        let resMemMB = await poller.getResidentMemoryMB()
        #expect(resMemMB > 0, "Resident memory should be > 0")
    }

    @Test
    func `calculates cpu utilization between snapshots`() async {
        let poller = SystemHardwarePoller()

        guard let snapshot1 = await poller.captureCpuSnapshot() else {
            Issue.record("Failed to capture first CPU snapshot")
            return
        }

        // Burn some CPU
        var sum = 0
        for i in 0 ..< 1_000_000 {
            sum += i
        }

        guard let snapshot2 = await poller.captureCpuSnapshot() else {
            Issue.record("Failed to capture second CPU snapshot")
            return
        }

        let utilization = await poller.calculateCpuUtilization(from: snapshot1, to: snapshot2)
        #expect(utilization >= 0.0 && utilization <= 1.0, "CPU utilization should be between 0 and 1")
    }
}

import Domain
import Foundation
@testable import MLInfrastructure
import Testing

@Suite("InferenceTelemetry")
struct InferenceTelemetryTests {
    private static let fixedDate = Date(timeIntervalSince1970: 1_700_000_000)

    private func makeMetrics(
        modelId: ModelID = ModelID("tiny.en"),
        audioDuration: TimeInterval = 10.0,
        inferenceDuration: TimeInterval = 2.0
    ) -> InferenceMetrics {
        InferenceMetrics(
            modelId: modelId,
            audioDuration: audioDuration,
            inferenceDuration: inferenceDuration,
            realTimeFactor: audioDuration / inferenceDuration,
            confidence: 0.95,
            sampleCount: 160_000,
            computeUnit: .cpuAndNeuralEngine,
            timestamp: Self.fixedDate
        )
    }

    // MARK: - record and recentMetrics

    @Test
    func `records single entry and retrieves it`() async {
        let telemetry = InferenceTelemetry()
        let m = makeMetrics()
        await telemetry.record(m)
        let recent = await telemetry.recentMetrics()
        #expect(recent.count == 1)
        #expect(recent[0].modelId == ModelID("tiny.en"))
    }

    @Test
    func `recentMetrics respects limit`() async {
        let telemetry = InferenceTelemetry()
        for i in 0 ..< 15 {
            await telemetry.record(makeMetrics(audioDuration: Double(i + 1) * 2.0))
        }
        let recent = await telemetry.recentMetrics(limit: 5)
        #expect(recent.count == 5)
    }

    @Test
    func `recentMetrics default limit is 10`() async {
        let telemetry = InferenceTelemetry()
        for _ in 0 ..< 20 {
            await telemetry.record(makeMetrics())
        }
        let recent = await telemetry.recentMetrics()
        #expect(recent.count == 10)
    }

    @Test
    func `recentMetrics returns all entries when count is within limit`() async {
        let telemetry = InferenceTelemetry()
        await telemetry.record(makeMetrics())
        await telemetry.record(makeMetrics())
        let recent = await telemetry.recentMetrics(limit: 10)
        #expect(recent.count == 2)
    }

    // MARK: - averageRTF

    @Test
    func `averageRTF returns nil when no entries for model`() async {
        let telemetry = InferenceTelemetry()
        let rtf = await telemetry.averageRTF(forModel: ModelID("base.en"))
        #expect(rtf == nil)
    }

    @Test
    func `averageRTF calculates correctly for single entry`() async {
        let telemetry = InferenceTelemetry()
        // audioDuration=10, inferenceDuration=2 → RTF=5.0
        await telemetry.record(makeMetrics(audioDuration: 10.0, inferenceDuration: 2.0))
        let rtf = await telemetry.averageRTF(forModel: ModelID("tiny.en"))
        #expect(rtf == 5.0)
    }

    @Test
    func `averageRTF calculates average across multiple entries`() async {
        let telemetry = InferenceTelemetry()
        // entry1: RTF = 10/2 = 5.0
        // entry2: RTF = 20/2 = 10.0
        // average = 7.5
        await telemetry.record(makeMetrics(audioDuration: 10.0, inferenceDuration: 2.0))
        await telemetry.record(makeMetrics(audioDuration: 20.0, inferenceDuration: 2.0))
        let rtf = await telemetry.averageRTF(forModel: ModelID("tiny.en"))
        #expect(rtf == 7.5)
    }

    @Test
    func `averageRTF filters by modelId`() async {
        let telemetry = InferenceTelemetry()
        // tiny.en: RTF = 10/2 = 5.0
        // base.en: RTF = 30/3 = 10.0
        await telemetry.record(makeMetrics(modelId: ModelID("tiny.en"), audioDuration: 10.0, inferenceDuration: 2.0))
        await telemetry.record(makeMetrics(modelId: ModelID("base.en"), audioDuration: 30.0, inferenceDuration: 3.0))
        let rtfTiny = await telemetry.averageRTF(forModel: ModelID("tiny.en"))
        let rtfBase = await telemetry.averageRTF(forModel: ModelID("base.en"))
        #expect(rtfTiny == 5.0)
        #expect(rtfBase == 10.0)
    }

    // MARK: - maxEntries cap / FIFO eviction

    @Test
    func `maxEntries caps stored metrics with FIFO eviction`() async {
        let telemetry = InferenceTelemetry(maxEntries: 3)
        // Record 5 entries with distinct audioDurations so we can identify them
        for i in 1 ... 5 {
            await telemetry.record(makeMetrics(audioDuration: Double(i) * 10.0))
        }
        // Only 3 entries should remain — the LAST 3 recorded (oldest evicted)
        let all = await telemetry.recentMetrics(limit: 1000)
        #expect(all.count == 3)
        #expect(all[0].audioDuration == 30.0) // 3rd recorded (entries 1 & 2 evicted)
        #expect(all[1].audioDuration == 40.0) // 4th recorded
        #expect(all[2].audioDuration == 50.0) // 5th recorded (newest)
    }

    // MARK: - Hardware Telemetry

    @Test
    func `records hardware stats via injected poller`() async throws {
        let mockPoller = MockSystemHardwarePoller()
        let telemetry = InferenceTelemetry(maxEntries: 10, poller: mockPoller)
        let m = makeMetrics()
        await telemetry.record(m)
        let recent = await telemetry.recentMetrics()
        #expect(recent.count == 1)

        let processMetrics = try #require(recent[0].processMetrics)
        // Mock getResidentMemoryMB() returns 64, production code does: 64 * 1024 * 1024
        #expect(processMetrics.processMemoryUsage == Int64(64 * 1024 * 1024))
        // Mock getPageFaults() returns 4444
        #expect(processMetrics.processPageFaults == 4444)
        // Mock getMlxMemoryUsageBytes() returns 2048 * 1024 * 1024
        #expect(processMetrics.processMlxMemoryUsage == Int64(2048) * 1024 * 1024)

        let envMetrics = try #require(recent[0].environmentMetrics)
        // Mock values match exactly
        #expect(envMetrics.osVersion == "macOS 15.1")
        #expect(envMetrics.cpuBrandString == "M2 Mock")
        #expect(envMetrics.physicalMemoryMB == 16384)
    }

    @Test
    func `print real hardware stats for user`() async throws {
        let poller = SystemHardwarePoller()
        print("\n===============================")
        print("📊 REAL HARDWARE STATS COLLECTED")
        print("===============================")
        print("🖥️  OS Version:      \(await poller.getOSVersion())")
        print("🧠  CPU Brand:       \(await poller.getCPUBrand())")
        print("💾  Physical Memory: \(await poller.getPhysicalMemoryMB()) MB")
        print("🔋  Battery:         \(await poller.getBatteryPercentage())%")
        print("🌡️   Thermal State:   \(await poller.getThermalState())")
        print("📈  Resident Memory: \(await poller.getResidentMemoryMB()) MB")
        print("📄  Page Faults:     \(await poller.getPageFaults())")
        print("===============================\n")
    }
}

private struct MockSystemHardwarePoller: SystemHardwarePollerProtocol {
    func getResidentMemoryMB() async -> Int64 { 64 }
    func getPageFaults() async -> Int { 4444 }
    func getCPUBrand() async -> String { "M2 Mock" }
    func getPhysicalMemoryMB() async -> Int { 16384 }
    func getOSVersion() async -> String { "macOS 15.1" }
    func getBatteryPercentage() async -> Int { 100 }
    func getThermalState() async -> String { "Nominal" }
    func getMlxMemoryUsageBytes() async -> Int64 { 2048 * 1024 * 1024 }

    func captureProcessSnapshot() async -> ProcessSnapshot? {
        return ProcessSnapshot(cpu: CpuSnapshot(user: 1, system: 1, idle: 1, nice: 1), memoryMB: 64, pageFaults: 4444, batteryPercentage: 100)
    }
    func calculateCpuUtilization(from: CpuSnapshot, to: CpuSnapshot) async -> Double {
        return 0.5
    }
}

